INSERT INTO `activities` VALUES ('4', '2', '天天红包', '估计会', '<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">活动不定时更新，请时刻关注，谢谢</span></p>\r\n<p class=\"at-font-red\" style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: red; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">【美东时间】按当日存款，当日抢红包，过期作废！</span></p>\r\n<p class=\"\" style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">活动规则请进入红包活动后查看详情</span></p>', '<p>抱抱你那你</p>', '<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">1、所有优惠以人民币（CNY）为结算金额，以美东时间（EDT）为计时区间。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">2、每位玩家、住址、电话、邮箱、相同支付卡/信用卡号、及共享电脑环境（例如网吧、其他公用电脑等）只能拥有一个会员享受优惠红利，如发现同一会员注册多账号行为，将收回全部优惠红利。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">3、所有的活动优惠特为玩家而设，如发现任何团体或个人，以不诚实的方式套取红利或任何威胁、滥用公司优惠等行为，公司保留冻结、取消该团体或个人账户及账户结余的权利。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">4、TG保留所有解释权，在任何时候都可以更改、停止、取消优惠活动</span>。</p>', '<p>不给你</p>', '0', 'images/d16ec86f5dcd0b8a06e8b83b4ba044bb.png', '0', '1', '2021-10-23 23:01:33', '2022-04-22 01:19:01');
INSERT INTO `activities` VALUES ('5', '2', '全勤奖 18888元月月回馈', null, '<p><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; background-color: #ffffff;\">我们很荣幸与您见证了这一路走来的点点滴滴，正是因为您的信赖与认可，我们才一直努力要求自己做得更好，我们将继续秉承&ldquo;惟有最好&rdquo;的品牌理念，以永不停息的创新精神，引领娱乐发展方向。只因您一如既往的支持与信赖，给了我们莫大的动力源泉，现金福利回馈给每一位支持TG的朋友！</span></p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 273px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">月有效投注</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">月存款天数</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">回馈彩金</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1万-10万</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">10~20（天）</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">58（元）</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1万-10万</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; fon