INSERT INTO `activities` VALUES ('8', '6', '电子3888亏损金 祝您一臂之力', null, '<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">即日起，会员于电子游艺当周亏损金额扣除返水金额后，计算周实际负盈利可得翻本保险金最高3888元。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">按美东时间计算，星期一至星期曰为一个周期。活动期间，会员自行统计于电子游艺周结区间所产生之总亏损金额，翻本保险金表如下：</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\">&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 189px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">亏损金额</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">额外加奖</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">提款要求</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">200元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">2元</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\" rowspan=\"8\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">&nbsp;1倍流水</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">500元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">8元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">28元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">2000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">58元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">5000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">288元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">10000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">588元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">50000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1888元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">100000元+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">3888元</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\">&nbsp;</p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">A、 会员于电子游艺当周输了5万，且当周返水金额为1.2万，计算周实际负盈利为5万-1.2=3.8万， 则会员可得翻本保险金588元。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">B、 会员于电子游艺当周输了 15万，且当周返水金额为8.4万，计算周实际负盈利为15万-8.4万=6.6万， 则会员可得翻本保险金1888元。</span></p>', null, '<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">1、所有优惠以人民币（CNY）为结算金额，以美东时间（EDT）为计时区间。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">2、每位玩家、住址、电话、邮箱、相同支付卡/信用卡号、及共享电脑环境（例如网吧、其他公用电脑等）只能拥有一个会员享受优惠红利，如发现同一会员注册多账号行为，将收回全部优惠红利。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">3、所有的活动优惠特为玩家而设，如发现任何团体或个人，以不诚实的方式套取红利或任何威胁、滥用公司优惠等行为，公司保留冻结、取消该团体或个人账户及账户结余的权利。</span></p>\r\n<p style=\"box-sizing: border-box; margin: 0px; padding: 0px; color: #333333; font-family: Arial, \'Microsoft JhengHei\', sans-serif; font-size: 15px; background-color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif;\">4、TG保留所有解释权，在任何时候都可以更改、停止、取消优惠活动。</span></p>', null, '0', 'images/28f1b7b44b234da7d0a6a1ae0e040c02.png', '1', '1', '2021-10-23 23:36:40', '2021-10-24 00:17:02');
INSERT INTO `activities` VALUES ('9', '6', '电子周周领 不论输赢', null, '<p><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; background-color: #ffffff;\">即日起所有进行电子游艺投注的会员，不计输贏，一周内保持5天存款金额大于1000，次周即可获得TG加赠的现金大礼包，走过路过不要错过！</span></p>\r\n<p>&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 42px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">天数条件</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">每日存款</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">礼包彩金</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">提款要求</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">5天以上</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1000元+</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">38元+</span></td>\r\n<td style=\"width: 25%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">一倍流水</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>', null, '<p style=\"box-sizing: border-box; margin: 0px; paddin