INSERT INTO `activities` VALUES ('10', '7', '彩票娱乐 码上豪礼', '1', '<table style=\"border-collapse: collapse; width: 100%; height: 160px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">彩票有效投注</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">加赠彩金</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">提款要求</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">5000+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">18元</span></td>\r\n<td style=\"width: 33.3333%; height: 139px; text-align: center;\" rowspan=\"7\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1倍流水</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">1万+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">28元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">5万+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">58元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">20万+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">108元</span></td>\r\n</tr>\r\n<tr style=\"height: 13px;\">\r\n<td style=\"width: 33.3333%; height: 13px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">50万+</span></td>\r\n<td style=\"width: 33.3333%; height: 13px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">288元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">200万+</span></td>\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-align: center; background-color: #ffffff;\">588元</span></td>\r\n</tr>\r\n<tr style=\"height: 21px;\">\r\n<td style=\"width: 33.3333%; height: 21px; text-align: center;\"><span style=\"color: #333333; font-family: arial, helvetica, sans-serif; font-size: 15px; text-